using CustomerManagement.API.Models;
using Microsoft.EntityFrameworkCore;

namespace CustomerManagement.API.Data;

/// <summary>Adds the next two original chapter arcs to each Development sample story.</summary>
public static class StoryExpansionSeeder
{
    private sealed record EpisodeSeed(string StoryTitle, int Chapter, string ChapterTitle, int Episode, string Title, string Content);

    private static readonly EpisodeSeed[] Episodes =
    [
        E("Tiệm sách ở cuối con hẻm", 5, "Người giữ chìa khóa", 1, "Chiếc chìa khóa đồng", "Một chiếc chìa khóa đồng xuất hiện trong hộp thư của tiệm, buộc bằng sợi chỉ màu nâu. Bảo nhận ra nó mở căn phòng kho đã bị niêm phong từ ngày mẹ Chi rời đi. Bên trong, họ tìm thấy những chiếc hộp ghi tên từng gia đình trong hẻm, mỗi hộp có một cuốn sách và một lời nhắn chưa gửi.\n\nChi không mở hộp của người còn sống nếu chưa hỏi ý kiến họ. Cô mang chìa khóa tới từng nhà, để người nhận tự quyết định có muốn đọc câu chuyện cũ hay không."),
        E("Tiệm sách ở cuối con hẻm", 5, "Người giữ chìa khóa", 2, "Bức thư gửi nhầm", "Trong một hộp không đề tên, Chi tìm thấy bức thư viết cho một người đã chuyển đi trước khi cô sinh ra. Địa chỉ trên phong bì dẫn tới tiệm sửa xe ở đầu phố, nơi ông Tư vẫn giữ một chiếc ghế trống cạnh cửa. Ông kể người nhận thư là em gái mình, hai người đã giận nhau vì một hiểu lầm nhỏ rồi không kịp làm lành.\n\nChi không thay ông trả lời thay người đã mất. Cô chỉ giúp ông viết lại điều ông muốn nói, rồi đặt lá thư vào cuốn sách ông từng mượn."),
        E("Tiệm sách ở cuối con hẻm", 5, "Người giữ chìa khóa", 3, "Ngày hộp được mở", "Cuối tuần, những người trong hẻm cùng ngồi ở sân tiệm để mở các hộp còn lại. Có người bật cười vì một bức ảnh cũ, có người lặng đi trước nét chữ của người thân. Chi nhận ra ký ức không phải món đồ để cất kín; nó cần được trao lại đúng người, vào đúng lúc.\n\nCô treo chiếc chìa khóa đồng lên móc cạnh cửa, kèm tấm bảng nhỏ mời mọi người gửi lời nhắn. Từ hôm đó, căn phòng kho không còn khóa, nhưng mỗi hộp đều có tên người được phép mở."),
        E("Tiệm sách ở cuối con hẻm", 6, "Ngày tiệm sách đổi biển hiệu", 1, "Dòng chữ mới", "Chủ nhà báo rằng tấm biển gỗ cũ đã mục và cần thay trước mùa mưa. Chi muốn khắc tên mẹ lên biển mới, nhưng những người trong hẻm đề nghị giữ lại tên tiệm sách mà ai cũng quen gọi. Bảo tìm được mẩu giấy mẹ cô để lại: “Cửa tiệm thuộc về người đang cần một câu chuyện.”\n\nHọ cùng chọn một tấm biển giản dị, chỉ ghi tên tiệm và giờ mở cửa. Chi thêm một dòng nhỏ phía dưới: ai có sách muốn trao đi đều có thể gõ cửa."),
        E("Tiệm sách ở cuối con hẻm", 6, "Ngày tiệm sách đổi biển hiệu", 2, "Buổi đọc sách đầu tiên", "Tấm biển mới vừa treo lên thì một nhóm trẻ trong hẻm mang ghế tới, xin tổ chức buổi đọc sách vào tối thứ sáu. Chi định từ chối vì tiệm không đủ chỗ, nhưng bác thợ khóa đã dọn sân, còn cô bán hoa đem đèn giấy tới treo dưới mái hiên. Mỗi người đọc một đoạn mình từng nhớ.\n\nKhông ai cần đọc thật hay. Một cậu bé đọc chậm từng chữ, và mọi người kiên nhẫn đợi cậu đến cuối trang. Tiệm sách lần đầu có một lịch sinh hoạt do chính độc giả viết lên."),
        E("Tiệm sách ở cuối con hẻm", 6, "Ngày tiệm sách đổi biển hiệu", 3, "Để cửa mở", "Một năm sau, Chi nhận được lời mời chuyển tiệm tới con phố lớn hơn. Nơi mới rộng rãi và có cửa kính sáng, nhưng cô lo những người trong hẻm sẽ không còn ghé ngang. Cô mang lời mời tới buổi đọc sách, để mọi người cùng nghĩ thay vì tự quyết một mình.\n\nHọ chọn giữ tiệm ở con hẻm và mở thêm một kệ sách lưu động đặt tại bến xe. Chi hiểu rằng một câu chuyện có thể đi xa mà không cần bỏ lại nơi nó bắt đầu. Cô khóa cửa tối hôm ấy, rồi quay lại mở ra vì có người vừa gõ cửa."),

        E("Bản đồ những vì sao", 5, "Thành phố dưới mặt hồ", 1, "Tọa độ chuyển động", "Một cơn gió lớn làm tấm bản đồ trên tường trường học bong khỏi lớp kính. Mai phát hiện các tọa độ đã thay đổi kể từ đêm ngôi sao thứ bảy xuất hiện. Khải so sánh bản đồ mới với những ghi chép của trẻ con và nhận ra các điểm sáng dịch chuyển theo mực nước hồ.\n\nHọ quay lại thung lũng khi mùa khô bắt đầu. Dưới đáy hồ lộ ra con đường lát đá, cùng những cột mốc khắc tên các gia đình từng sống ở đó. Bản đồ không dẫn tới một thành phố bị mất; nó đang cập nhật nơi những người còn sống nhớ về."),
        E("Bản đồ những vì sao", 5, "Thành phố dưới mặt hồ", 2, "Những căn nhà lộ mái", "Nước rút thấp hơn dự đoán, để lộ mái ngói của một dãy nhà dưới lòng hồ. Mai không cho ai bước xuống ngay vì lớp bùn còn mềm. Họ dựng hàng rào và mời các gia đình cũ tới xem từ bờ, mỗi người kể lại căn nhà của mình bằng những chi tiết không có trên bất kỳ tấm bản đồ nào.\n\nMột người nhớ cây khế cạnh giếng, người khác nhớ cửa sổ luôn mở về hướng đông. Khải đánh dấu những lời kể riêng biệt bằng màu khác nhau, để dữ kiện và ký ức có thể cùng tồn tại."),
        E("Bản đồ những vì sao", 5, "Thành phố dưới mặt hồ", 3, "Con đường không ngập", "Trước khi nước dâng trở lại, Mai và Khải đi theo con đường lát đá tới quảng trường cũ. Ở giữa quảng trường là một phiến đá trống, không khắc tên người hay năm tháng. Bà lão ở rừng bạc bảo đó là chỗ dành cho những người chưa sinh ra, để họ có thể tự viết tên mình khi tìm thấy nơi này.\n\nMai chụp lại phiến đá nhưng không mang nó đi. Họ đánh dấu lối xuống hồ trên bản đồ công khai, kèm cảnh báo về mùa nước, để người khác có thể tìm hiểu mà không làm hư hại di tích."),
        E("Bản đồ những vì sao", 6, "Bức thư gửi ngôi sao", 1, "Lá thư từ đài quan sát", "Một phong thư được gửi tới đài quan sát, ghi địa chỉ người nhận là “ngôi sao thứ bảy”. Bên trong là lời nhắn của một học sinh ở thành phố xa, em đã nghe chuyện về thung lũng và muốn biết tên bà cố mình có nằm trên bức tường hay không. Mai không tìm thấy tên ấy trong hồ sơ, nhưng nhận ra dấu họa tiết em gửi trùng với ký hiệu trên bản đồ.\n\nCô viết thư hồi âm, hỏi em muốn bổ sung điều gì vào câu chuyện của gia đình. Khải đặt lá thư cạnh kính thiên văn, như thể khoảng cách giữa hai nơi có thể đo bằng một nét bút."),
        E("Bản đồ những vì sao", 6, "Bức thư gửi ngôi sao", 2, "Tên gọi được thêm vào", "Học sinh ấy cùng mẹ đến thung lũng vào kỳ nghỉ. Họ mang theo một cuốn sổ gia đình với tên bà cố được viết bằng hai cách khác nhau. Mai không tự sửa bức tường; cô mời hai mẹ con kể lại vì sao cách viết ấy thay đổi theo thời gian.\n\nKhải đặt thêm một bảng nhỏ bên cạnh bản đồ, ghi nguồn của từng cái tên và ngày được xác nhận. Cậu bé trong trường đề nghị có chỗ ghi những tên chưa chắc chắn. Bức tường lớn lên không chỉ bằng câu trả lời, mà còn bằng những câu hỏi được giữ lại."),
        E("Bản đồ những vì sao", 6, "Bức thư gửi ngôi sao", 3, "Người vẽ tiếp bản đồ", "Đêm cuối trước khi trở về, cậu bé nhìn qua kính thiên văn và nói ngôi sao thứ bảy có màu giống ánh đèn trong bếp nhà bà cố. Mai hiểu rằng mỗi người tìm thấy một bầu trời riêng trong cùng một chòm sao. Cô trao cho em một bản đồ trống, không đánh dấu sẵn con đường nào.\n\nTại đài quan sát, họ ghim bức thư đầu tiên lên bảng thông tin, bên cạnh những lá thư khác gửi từ nhiều nơi. Tấm bản đồ gốc vẫn nằm trong tủ kính, còn bản đồ mới được để mở trên bàn cho người đến sau viết tiếp."),

        E("Mùa mưa trên mái ngói", 5, "Chuyến tàu mùa nước nổi", 1, "Tấm vé không ghi ga", "Năm sau, Hạ nhận được tấm vé tàu chỉ ghi ngày khởi hành, không có ga đến. Người gửi là bà cụ từng ngồi cuối toa, nay nhờ họ mang một chiếc hộp tới thị trấn ven sông trước khi mùa nước nổi bắt đầu. Minh tìm tuyến đường cũ trong cuốn sổ ga, nhưng chuyến tàu ấy đã bị bỏ khỏi lịch nhiều năm.\n\nHọ quyết định đi bằng xe buýt và phà, mang theo chiếc ô xanh đã được vá lại. Dọc đường, Hạ ghi tên từng bến dừng vào mặt sau tấm vé, như thể hành trình sẽ tự chọn nơi kết thúc."),
        E("Mùa mưa trên mái ngói", 5, "Chuyến tàu mùa nước nổi", 2, "Căn nhà trên cọc gỗ", "Thị trấn ven sông chỉ hiện ra khi nước ròng. Bà cụ đón họ tại một căn nhà dựng trên cọc gỗ, nơi chiếc hộp được gửi tới cho một lớp học nhỏ. Trong hộp là những tấm bản đồ mùa lũ do học sinh vẽ, ghi vị trí nhà cao, trạm thuốc và nơi có thể neo thuyền.\n\nMinh nhận ra nét chữ trong một tấm bản đồ là của mẹ mình. Hạ hiểu bà cụ không nhờ họ chuyển đồ vật; bà muốn những người trong thị trấn gặp lại nhau để cùng cập nhật những điểm an toàn trước mùa mưa mới."),
        E("Mùa mưa trên mái ngói", 5, "Chuyến tàu mùa nước nổi", 3, "Con đường nổi", "Cả lớp học cùng người lớn dán các bản đồ lên tường nhà văn hóa. Họ phát hiện một cây cầu gỗ đã mục và con đường tới trạm thuốc bị sạt lở. Minh gọi cho những người phụ trách sửa chữa, còn Hạ ghi rõ ngày kiểm tra kế tiếp bên cạnh từng ký hiệu.\n\nKhi nước dâng vào buổi tối, chiếc ô xanh được chuyền tay qua các căn nhà để đưa người già tới nơi cao ráo. Tấm vé không có ga đến được ghim lên bản đồ, như lời nhắc rằng có những chuyến đi kết thúc bằng việc giúp người khác tìm đường."),
        E("Mùa mưa trên mái ngói", 6, "Ga cuối mùa hạ", 1, "Sân ga được sửa lại", "Nhà ga số bốn sắp được chuyển thành kho hàng. Minh nhận được tin báo và tìm lại cuốn sổ chuyến đi mà người soát vé cũ từng trao. Hạ đề nghị gặp cư dân quanh ga trước khi quyết định nên giữ hay bỏ nơi này. Họ hỏi từng người nhà ga đã có ý nghĩa gì trong những lần đi xa, trở về hoặc chờ một tin tức.\n\nNhững câu trả lời khác nhau đến mức không thể chọn một câu chuyện duy nhất. Họ xin một khoảng thời gian để tổ chức buổi gặp mặt ngay trên sân ga trước ngày công trình bắt đầu."),
        E("Mùa mưa trên mái ngói", 6, "Ga cuối mùa hạ", 2, "Chuyến tàu của những lá thư", "Buổi gặp mặt có người mang theo thư cũ, có người mang vé tàu đã phai màu. Bà cụ cuối toa gửi một bức thư ghi địa chỉ em gái mình, lần này có hồi âm. Minh đọc lịch tàu cũ cho lũ trẻ nghe, còn Hạ dựng một chiếc bàn để mọi người viết lời nhắn cho người sắp rời thị trấn.\n\nKhông ai yêu cầu giữ nhà ga nguyên trạng. Cư dân đề xuất dành phòng chờ làm nơi trao đổi sách và thư, còn sân ga vẫn hoạt động cho tuyến tàu chở khách. Một tấm bảng ghi rõ quyết định ấy được ký bởi những người sống quanh ga."),
        E("Mùa mưa trên mái ngói", 6, "Ga cuối mùa hạ", 3, "Lời hẹn chuyến trở về", "Đầu mùa hạ, nhà ga mở cửa trở lại với mái ngói mới và chiếc đồng hồ được sửa đúng giờ. Minh cùng Hạ đi chuyến tàu đầu tiên qua ga, không phải để rời khỏi thị trấn mà để kiểm tra xem những tấm biển chỉ dẫn đã rõ chưa. Bà cụ ngồi cạnh cửa sổ, mang theo một bó hoa dành cho người em gái.\n\nKhi tàu lăn bánh, sân ga vang lên tiếng chào của những người ở lại. Hạ cất tấm vé cũ vào cuốn sổ, để dành chỗ cho chuyến tiếp theo. Mùa hạ rồi cũng qua, nhưng giờ đây ai cũng biết đường quay về."),

        E("Kẻ giữ ngọn hải đăng", 5, "Con tàu không có tên", 1, "Ánh đèn ngoài khơi", "Một đêm trời lặng, ngọn hải đăng phát hiện ánh đèn lạ ngoài khơi dù không có tàu nào trong danh sách cập bến. An ghi giờ, hướng gió và khoảng cách ước tính vào sổ trực. Sáng hôm sau, một chiếc thuyền nhỏ dạt vào bờ, trên mạn thuyền chỉ còn vết sơn nơi tên tàu từng được viết.\n\nNgười lái thuyền không nhớ mình đã đi bao lâu. Ông chỉ giữ một chiếc la bàn đứng im và tấm ảnh chụp bến cảng trước khi cơn bão lớn cuốn mất nhà cửa."),
        E("Kẻ giữ ngọn hải đăng", 5, "Con tàu không có tên", 2, "Sổ trực bị xé", "Trong sổ trực cũ, An tìm thấy nhiều trang bị xé đúng vào những ngày có ánh đèn lạ. Người tiền nhiệm đã không báo cáo chúng, nhưng để lại một dòng ghi chú: “Đừng gọi họ là tàu ma; hãy hỏi xem họ cần gì.” An lần theo danh sách cư dân mất tích và tìm được gia đình của người lái thuyền.\n\nHọ đón ông trong căn nhà mới gần cảng. Không ai hỏi ông đã biến mất ở đâu trước khi ông sẵn sàng kể. Chiếc la bàn được đặt trên bàn ăn, nơi cả nhà cùng bàn cách sửa lại bến thuyền."),
        E("Kẻ giữ ngọn hải đăng", 5, "Con tàu không có tên", 3, "Tên được sơn lại", "Người lái thuyền trở lại hải đăng sau vài ngày, lần này mang theo danh sách những con tàu từng trú bão tại vịnh. Ông nhận ra một số tên đã bị xóa khỏi sổ cảng vì hồ sơ thất lạc. An xin phép gia đình để bổ sung tên họ vào tấm bảng tưởng niệm dưới chân tháp.\n\nKhi nét sơn cuối cùng khô, đèn biển quét qua mặt nước như mọi đêm. An không còn xem những ánh đèn ngoài khơi là điềm báo. Đó có thể chỉ là một lời nhắn cần được người trên bờ trả lời."),
        E("Kẻ giữ ngọn hải đăng", 6, "Ngày đổi người trực", 1, "Bàn giao chiếc đèn", "Sau nhiều năm trực đêm, An được yêu cầu bàn giao hải đăng cho một người mới. Cô dạy người kế nhiệm cách nghe tiếng máy rung khác thường, cách ghi lại từng lần thời tiết đổi và cách giữ liên lạc với tàu cá trong sương. Người mới thuộc hết quy trình nhưng chưa hiểu vì sao An luôn để một ngọn đèn nhỏ ở cửa phòng trực.\n\nAn kể đó là lời hẹn với những người đi biển, để họ biết trên bờ vẫn có người thức. Cô trao cuốn sổ trực cho người mới, nhưng giữ lại một trang trắng cuối cùng."),
        E("Kẻ giữ ngọn hải đăng", 6, "Ngày đổi người trực", 2, "Cơn bão đến sớm", "Cơn bão đầu mùa đến sớm hơn dự báo. Người trực mới định đóng cửa tháp theo quy trình, nhưng An nhận ra luồng gió đã đổi chiều và có thuyền đánh cá chưa kịp về. Họ dùng tín hiệu dự phòng để hướng dẫn từng thuyền vào vịnh, trong khi đội cứu hộ đưa người dân khỏi dải bờ thấp.\n\nĐèn biển không thể xua bão, nhưng ánh sáng đều đặn giúp những con thuyền giữ hướng. Sau đêm dài, người trực mới tự ghi lại diễn biến và thêm một ghi chú cho người kế tiếp, bắt đầu truyền thống mà An từng nghĩ chỉ mình hiểu."),
        E("Kẻ giữ ngọn hải đăng", 6, "Ngày đổi người trực", 3, "Người canh sáng tiếp theo", "Khi trời quang, An rời đảo bằng chuyến thuyền buổi sớm. Người trực mới đứng trên ban công vẫy tay, còn ngọn đèn tiếp tục quay theo nhịp quen thuộc. Trước khi đi, An đặt cuốn sổ lên bàn và viết vào trang cuối tên những người đã giúp nhau qua cơn bão.\n\nNhiều tháng sau, cô nhận được một bức thư từ đảo, kể rằng ngọn đèn nhỏ ở cửa vẫn được thắp mỗi tối. An cất thư cạnh chiếc chìa khóa cũ, biết rằng giữ ánh sáng không nhất thiết phải đứng mãi ở một nơi."),

