        E("Vườn thư gửi mai sau", 5, "Hạt giống trong phong bì", 3, "Mầm cây đầu tiên", "Sau cơn mưa dài, một mầm cây nhỏ nhú lên ở góc luống mà cả nhóm tưởng đã bỏ cuộc. Không ai dám chạm vào nó. Họ dựng một hàng rào thấp và thay nhau ghi lại hình dáng chiếc lá mỗi ngày. An Nhiên gửi ảnh cho người viết thư, nhưng bưu điện trả lại phong bì vì địa chỉ không còn tồn tại.\n\nThay vì vứt lá thư đi, cô đặt nó vào hòm thư chung để người lạ có thể hồi âm. Vài tuần sau, một người cháu của người làm vườn tìm tới, mang theo bản đồ khu đất cũ và câu chuyện về giống cây ấy."),
        E("Vườn thư gửi mai sau", 6, "Bản đồ của khu vườn", 1, "Ranh giới mới", "Khu đất cạnh vườn được rao bán, khiến con đường dẫn nước có nguy cơ bị chặn. An Nhiên cùng cư dân tìm lại bản đồ cũ trong hồ sơ phường và phát hiện con mương vốn nằm ngoài ranh giới khu vườn. Họ mời chủ đất mới tới xem hiện trạng trước khi đưa ra yêu cầu.\n\nNgười chủ không biết con mương còn phục vụ nhiều hộ dân. Hai bên cùng đo lại lối nước và vẽ một sơ đồ mới, ghi rõ phần cần giữ thông thoáng. Tấm bản đồ được đặt tại nhà sinh hoạt chung để mọi người có thể kiểm tra."),
        E("Vườn thư gửi mai sau", 6, "Bản đồ của khu vườn", 2, "Người nhận thư tương lai", "Một nhóm học sinh đề nghị gửi thư cho chính mình sau mười năm. Các em kể điều muốn khu vườn còn giữ được, từ bóng cây lớn tới chiếc ghế nơi bà ngoại thường nghỉ. An Nhiên chỉ nhận những phong thư có địa chỉ người gửi và ngày được phép mở, rồi ghi chúng vào sổ lưu trữ.\n\nCô lo rằng vài năm sau sẽ không ai nhớ tới hòm thư. Bác nông dân đề nghị mỗi mùa thu tổ chức một buổi kiểm tra thư, không mở phong bì mà chỉ xác nhận chúng vẫn còn ở đó. Khu vườn có thêm một việc để cùng chờ đợi."),
        E("Vườn thư gửi mai sau", 6, "Bản đồ của khu vườn", 3, "Mùa thu gửi đi", "Mùa thu đến, khu vườn thu được lứa hạt đầu tiên từ những cây đã lớn lên ở đây. Một phần được giữ lại, phần còn lại gửi cho trường học và các khu đất cộng đồng khác. An Nhiên viết kèm hướng dẫn chăm sóc, ghi cả những điều từng làm họ thất bại để người nhận đỡ lặp lại.\n\nHòm thư vẫn đầy những phong bì dành cho tương lai. Cô khóa nó lại bằng chiếc chốt gỗ, không phải để giữ bí mật mà để thời gian có cơ hội hoàn thành lời hẹn. Trên bản đồ, khu vườn giờ có thêm những điểm mới do người khác gieo trồng."),

        E("Thành phố không ngủ", 5, "Tiếng gọi từ tầng mười hai", 1, "Cuộc gọi lúc 00:17", "Đúng mười hai giờ mười bảy phút, tổng đài cũ trong thư viện reo lên dù dây điện đã bị tháo. Lam nhấc máy và nghe một giọng nói hỏi đường tới con phố không còn trên bản đồ. Cô nhận ra số máy trùng với danh sách điện thoại của trạm đồng hồ bị bỏ hoang.\n\nPhúc lần theo đường dây trong kho lưu trữ, phát hiện nó nối tới một tòa nhà chưa từng được đánh số. Họ tìm được tầng mười hai, nơi bảng thang máy chỉ có các số từ một tới mười một."),
        E("Thành phố không ngủ", 5, "Tiếng gọi từ tầng mười hai", 2, "Căn phòng lưu địa chỉ", "Sau cánh cửa cuối hành lang là căn phòng chứa hàng trăm tấm biển tên đường. Mỗi tấm có một chiếc chìa khóa nhỏ và một mẩu thư chưa gửi. Lam không mang chúng đi mà lập danh mục, gọi những người có thể xác nhận nguồn gốc từng địa chỉ. Một vài cái tên thuộc về khu phố đã bị san bằng, số khác chưa từng xuất hiện trong hồ sơ.\n\nPhúc nghe lại cuộn băng dưới cầu và tìm thấy cùng một giọng đọc danh sách. Người nói đang cố giữ các địa chỉ khỏi biến mất, nhưng không biết cách trao chúng lại cho cư dân."),
        E("Thành phố không ngủ", 5, "Tiếng gọi từ tầng mười hai", 3, "Danh bạ của người còn sống", "Lam tổ chức một buổi tiếp nhận ký ức tại thư viện. Người dân mang ảnh, thư và những tấm biển cũ tới đối chiếu. Căn phòng tầng mười hai được mở cửa công khai vào ban ngày, còn các chìa khóa được trao cho những gia đình có thể xác nhận từng con phố.\n\nKhông phải địa chỉ nào cũng tìm được chủ nhân. Lam ghi rõ điều chưa biết thay vì tự điền câu trả lời. Đêm đó, tổng đài reo thêm một lần; lần này người gọi để lại tên mình và hẹn đến thư viện vào sáng hôm sau."),
        E("Thành phố không ngủ", 6, "Bản tin lúc bình minh", 1, "Một giờ để kể", "Đài phát thanh địa phương đề nghị Lam kể về những con phố đã biến mất trong bản tin sáng. Cô từ chối đọc một danh sách khô khan và mời cư dân tự gọi vào chương trình để nói về nơi họ từng sống. Phúc dựng một bản đồ lớn trong phòng thu, ghi mỗi địa chỉ bằng màu của người kể.\n\nĐường dây liên tục bận, nhưng những khoảng lặng giữa các cuộc gọi cũng được giữ lại. Một người phụ nữ chỉ muốn nghe tên con hẻm cũ được đọc lên. Khi tên ấy vang qua loa, bà nói rằng mình đã có thể ngủ yên hơn."),
        E("Thành phố không ngủ", 6, "Bản tin lúc bình minh", 2, "Tiếng nói ở đầu dây", "Một người gọi nặc danh kể rằng mình từng sửa các bảng tên phố theo lệnh quy hoạch, nhưng đã giữ lại vài tấm biển cũ. Ông muốn trả chúng về thư viện mà không nêu tên. Lam đồng ý nhận hiện vật ẩn danh, nhưng đề nghị ghi lại hoàn cảnh để người xem hiểu vì sao chúng bị tháo xuống.\n\nPhúc đặt những tấm biển cạnh bản đồ và không cố sắp chúng thành một con đường hoàn chỉnh. Mỗi tấm có một câu chuyện khác nhau, có nơi người dân muốn phục hồi tên cũ, có nơi họ chọn giữ tên mới."),
        E("Thành phố không ngủ", 6, "Bản tin lúc bình minh", 3, "Thành phố đi ngủ", "Chương trình phát thanh kết thúc khi mặt trời lên. Lam bước ra quảng trường và thấy người bán hàng đêm đang dọn quầy, còn nhóm học sinh chuẩn bị mở cửa thư viện. Họ cùng treo bản đồ mới trong phòng đọc, bên dưới là hướng dẫn gửi thêm thông tin và cách kiểm chứng lời kể.\n\nĐêm ấy, thành phố vẫn sáng đèn ở vài con phố, nhưng Lam không còn cảm thấy nó đang cố thức để chống lại ký ức. Cô tắt chiếc máy ghi âm, để dành phần còn lại cho buổi phát thanh ngày mai." )
    ];

    public static async Task SeedAsync(ApplicationDbContext context, CancellationToken cancellationToken = default)
    {
        var now = DateTime.UtcNow;
        foreach (var storyEpisodes in Episodes.GroupBy(item => item.StoryTitle))
        {
            var story = await context.Stories.SingleOrDefaultAsync(item => item.Title == storyEpisodes.Key, cancellationToken);
            if (story is null) continue;

            var groups = await context.StoryChapters.Where(item => item.StoryId == story.Id).ToDictionaryAsync(item => item.Number, cancellationToken);
            var existingEpisodes = await context.Chapters.Where(item => item.StoryId == story.Id)
                .Select(item => new { StoryChapterNumber = item.StoryChapter.Number, item.EpisodeNumber })
                .ToListAsync(cancellationToken);
            var episodeKeys = existingEpisodes.Select(item => (item.StoryChapterNumber, item.EpisodeNumber)).ToHashSet();
            var sequence = await context.Chapters.Where(item => item.StoryId == story.Id).MaxAsync(item => (int?)item.Number, cancellationToken) ?? 0;

            foreach (var episodeSeed in storyEpisodes)
            {
                if (!groups.TryGetValue(episodeSeed.Chapter, out var group))
                {
                    group = new StoryChapter { StoryId = story.Id, Number = episodeSeed.Chapter, Title = episodeSeed.ChapterTitle };
                    context.StoryChapters.Add(group);
                    groups.Add(episodeSeed.Chapter, group);
                }
                else if (group.Title != episodeSeed.ChapterTitle)
                {
                    group.Title = episodeSeed.ChapterTitle;
                }

                if (!episodeKeys.Add((episodeSeed.Chapter, episodeSeed.Episode))) continue;

                sequence++;
                context.Chapters.Add(new Chapter
                {
                    StoryId = story.Id,
                    StoryChapter = group,
                    Number = sequence,
                    EpisodeNumber = episodeSeed.Episode,
                    Title = episodeSeed.Title,
                    Content = episodeSeed.Content,
                    IsFree = story.AccessType == "Mixed" && story.FreeChapterCount >= sequence,
                    PublishAt = now.AddDays(-episodeSeed.Chapter).AddHours(-episodeSeed.Episode * 3),
                    ViewCount = 0
                });
                story.UpdatedAt = now;
            }
        }

        await context.SaveChangesAsync(cancellationToken);
    }

    private static EpisodeSeed E(string story, int chapter, string chapterTitle, int episode, string title, string content) =>
        new(story, chapter, chapterTitle, episode, title, content);
}
